using CareComply.Application.Abstractions.Authentication; using CareComply.Application.Abstractions.Clients; using CareComply.Application.Auditing; using CareComply.Application.Authorization; using CareComply.Domain.Clients; using FluentValidation; using Mediator;
namespace CareComply.Application.Features.ClientHospitalizations;
public sealed record ListClientHospitalizationsQuery(Guid ClientId):IQuery<HospitalizationResult>,IRequirePermission{public string RequiredPermission=>Permissions.ClientHospitalization.View;}
public sealed record SaveClientHospitalizationCommand(Guid ClientId,Guid? Id,string HospitalName,DateTimeOffset AdmittedAtUtc,DateTimeOffset? DischargedAtUtc,string Reason,string? Diagnosis,string? DischargeInstructions,string? EditorVersion):ICommand<HospitalizationResult>,IRequirePermission,IAuditableRequest<HospitalizationResult>{public string RequiredPermission=>Id.HasValue?Permissions.ClientHospitalization.Edit:Permissions.ClientHospitalization.Create; public AuditEvent CreateAuditEvent(HospitalizationResult response)=>new(Id.HasValue?"ClientHospitalization.Updated":"ClientHospitalization.Created","ClientHospitalization",(Id??ClientId).ToString(),response.Mutation?.Status==HospitalizationMutationStatus.Succeeded?AuditOutcome.Succeeded:AuditOutcome.Failed);}
public sealed record HospitalizationResult(HospitalizationList? List,HospitalizationMutation? Mutation,AuthorizationFailure? AuthorizationFailure){public string ReasonCode=>AuthorizationFailure?.ToString()??Mutation?.Status.ToString()??"Succeeded";public static HospitalizationResult From(HospitalizationList? x)=>new(x,null,null);public static HospitalizationResult From(HospitalizationMutation x)=>new(null,x,null);public static HospitalizationResult Denied(AuthorizationFailure x)=>new(null,null,x);}
public sealed class HospitalizationAuthorizationFailureFactory:IAuthorizationFailureResultFactory<HospitalizationResult>{public HospitalizationResult Create(AuthorizationFailure failure)=>HospitalizationResult.Denied(failure);}
public sealed class ListClientHospitalizationsHandler(IClientHospitalizationStore store):IQueryHandler<ListClientHospitalizationsQuery,HospitalizationResult>{public async ValueTask<HospitalizationResult> Handle(ListClientHospitalizationsQuery query,CancellationToken cancellationToken)=>HospitalizationResult.From(await store.List(query.ClientId,cancellationToken));}
public sealed class SaveClientHospitalizationHandler(IClientHospitalizationStore store,ICurrentActor actor,TimeProvider clock):ICommandHandler<SaveClientHospitalizationCommand,HospitalizationResult>{public async ValueTask<HospitalizationResult> Handle(SaveClientHospitalizationCommand command,CancellationToken cancellationToken){var now=clock.GetUtcNow();return HospitalizationResult.From(command.Id.HasValue?await store.Update(new(command.ClientId,command.Id.Value,command.HospitalName,command.AdmittedAtUtc,command.DischargedAtUtc,command.Reason,command.Diagnosis,command.DischargeInstructions,command.EditorVersion??string.Empty,now),cancellationToken):await store.Create(new(command.ClientId,command.HospitalName,command.AdmittedAtUtc,command.DischargedAtUtc,command.Reason,command.Diagnosis,command.DischargeInstructions,actor.UserId!.Value,now),cancellationToken));}}
public sealed class SaveClientHospitalizationValidator:AbstractValidator<SaveClientHospitalizationCommand>{public SaveClientHospitalizationValidator(){RuleFor(x=>x.ClientId).NotEmpty();RuleFor(x=>x.HospitalName).NotEmpty().MaximumLength(ClientHospitalization.HospitalMaxLength);RuleFor(x=>x.Reason).NotEmpty().MaximumLength(ClientHospitalization.ReasonMaxLength);RuleFor(x=>x.Diagnosis).MaximumLength(ClientHospitalization.DetailsMaxLength);RuleFor(x=>x.DischargeInstructions).MaximumLength(ClientHospitalization.DetailsMaxLength);RuleFor(x=>x.DischargedAtUtc).GreaterThanOrEqualTo(x=>x.AdmittedAtUtc).When(x=>x.DischargedAtUtc.HasValue);RuleFor(x=>x.EditorVersion).NotEmpty().Length(64).When(x=>x.Id.HasValue);}}
